WITH reason_agg AS ( SELECT cp.cp_catalog_page_id AS cp_id, cp.cp_department, r.r_reason_desc, cd.cd_gender, COUNT(*) AS return_events, SUM(cr.cr_return_amount) AS total_return_amount FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk WHERE cr.cr_return_quantity >= 5 AND cp.cp_department = 'Electronics' GROUP BY cp.cp_catalog_page_id, cp.cp_department, r.r_reason_desc, cd.cd_gender ), windowed AS ( SELECT cp_id, cp_department, r_reason_desc, cd_gender, return_events, total_return_amount, SUM(total_return_amount) OVER (PARTITION BY cp_department) AS dept_total_return FROM reason_agg ) SELECT cp_id, cp_department, r_reason_desc, cd_gender, return_events, total_return_amount, dept_total_return, CASE WHEN total_return_amount = dept_total_return THEN 'Dept Max' ELSE 'Other' END AS dept_category FROM windowed WHERE return_events >= 3 ORDER BY dept_total_return DESC, cp_id
